#include "StyleAI/StyleDataset.h"
#include <filesystem>
#include <iostream>
int main(){namespace fs=std::filesystem;const auto root=fs::current_path()/".phase45-folder-test";std::error_code ec;fs::remove_all(root,ec);for(const char* name:{"A","B","C"})fs::create_directories(root/name);std::vector<fs::path> sources;for(const auto&e:fs::directory_iterator("resources"))if(e.path().extension()==".png")sources.push_back(e.path());if(sources.size()<8)return 2;size_t n=0;for(int f=0;f<3;++f)for(int i=0;i<(f<2?3:2);++i)fs::copy_file(sources[n++],root/(f==0?"A":f==1?"B":"C")/(std::to_string(i+1)+".png"));StyleDataset dataset;std::string error;if(!dataset.Create(root/"dataset","FolderTest",error))return 1;for(const char* name:{"A","B","C"})for(const auto&e:fs::directory_iterator(root/name))if(!dataset.AddImage(e.path(),error))return 1;if(!dataset.SaveCaption(0,"test caption",error))return 1;if(dataset.GetItems().size()!=8||dataset.GetItems().front().localImagePath.filename()!="000001.png"||dataset.GetItems().back().localImagePath.filename()!="000008.png"||!dataset.ContainsSource(root/"A"/"1.png"))return 1;if(!dataset.SaveAs(root/"SosoStyle","SosoStyle",error)||dataset.GetName()!="SosoStyle"||dataset.GetItems().size()!=8||dataset.GetItems()[0].caption!="test caption"||!fs::is_regular_file(root/"SosoStyle"/"dataset.json"))return 1;if(dataset.SaveAs(root/"SosoStyle","Duplicate",error)||error!="Dataset already exists.")return 1;std::cout<<"Folder import and Save Dataset As test passed.\n";fs::remove_all(root,ec);return 0;}
